<?php
declare(strict_types=1);
const OP='int-anex-page2-ledger-readback-20260919-v1',SEALED='int-anex-page2-current-20260919-v1';
function safeError(string$s):string{$s=preg_replace('/Bearer\s+[^\s]+/i','Bearer [redacted]',$s);$s=preg_replace('/[A-Za-z0-9_-]{32,}/','[opaque]',$s);return mb_substr(trim($s),0,500,'UTF-8');}
function main():array{$dir=rtrim((string)getenv('HOME'),'/').'/.anytour-ops/'.SEALED;if(!is_dir($dir)||is_link($dir))throw new RuntimeException('LEDGER');$files=[];foreach(scandir($dir)?:[]as$n){if($n==='.'||$n==='..')continue;$p=$dir.'/'.$n;if(is_file($p)&&!is_link($p))$files[$n]=['bytes'=>filesize($p),'sha256'=>hash_file('sha256',$p)];}
 $page=null;if(is_file($dir.'/page2.raw.json'))try{$j=json_decode((string)file_get_contents($dir.'/page2.raw.json'),true,64,JSON_THROW_ON_ERROR);$d=$j['SearchTour_PRICES']??$j;$prices=is_array($d)&&is_array($d['prices']??null)?$d['prices']:[];$hotels=[];$target=[];foreach($prices as$r){if(!is_array($r))continue;$id=$r['hotelKey']??null;if((is_int($id)||is_string($id))&&preg_match('/^[1-9][0-9]{0,8}$/D',(string)$id))$hotels[(string)$id]=1;$name=$r['hotel']??null;if(is_string($name)&&stripos($name,'IC HOTELS RESIDENCE')!==false)$target[]=['hotelKey'=>(string)$id,'name'=>$name];}$page=['rows'=>count($prices),'unique_hotels'=>count($hotels),'searchKey_present'=>is_string($d['searchKey']??null)&&$d['searchKey']!=='','target_matches'=>$target];}catch(Throwable){$page=['parse_error'=>true];}
 return['operation'=>OP,'sealed_operation'=>SEALED,'files'=>$files,'page2'=>$page,'error'=>is_file($dir.'/error.log')?safeError((string)file_get_contents($dir.'/error.log')):null,'supplier_page2_captured'=>$page!==null,'supplier_calls_unknown'=>true,'db_writes'=>0,'runtime_writes'=>0];}
if(PHP_SAPI==='cli'){try{echo json_encode(main(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR)."\n";}catch(Throwable){fwrite(STDERR,"ANEX_PAGE2_LEDGER_READBACK_FAILED\n");exit(2);}}
